// What the original programs call in the runtime, and where BlitzLLVM has it.
#pragma once
#include <string>
#include <vector>

namespace blitz::recompiler {
	struct command {
		std::string name;   // Lowercase name of the command: entityx
		std::string symbol; // Function in the BlitzLLVM runtime: bb_entity_x
		char        ret;    // v nothing, i Int32, f Float32, s String, u UInt64
		std::string params; // One of i, f, s for each parameter (BlitzLLVM may have more than the original)
		std::vector<double> defaults; // The value of each parameter when a caller leaves it out
	};

	/** Looks for a command by the lowercase name the original compiler used (the symbol is "_f" followed by it). */
	command const* find_command(std::string const& name);

	/** Every command, for statistics. */
	std::vector<command> const& all_commands();
} // namespace blitz::recompiler
